#!/usr/bin/env node
/**
 * 生成插件自带的 bundle 层：./cordis.patch.yml（一个 - insert: 里只有一行 preset）
 *   preset-engineer —— 「Engineer mode」，其 plugins 里带 skill-engineer（8 个常驻技能 + 自动触发规则）。
 *
 * 基底默认用官方 ptc 预设（含 code_run / code_tools_* 这套），可用 DS_STACK_BASE 切回 standard 等：
 *   DS_STACK_BASE=standard node scripts/build-bundle.mjs
 *
 * 只做可枚举替换，并断言「反向替换回去必须逐字节等于基底预设」。
 *
 *   node scripts/build-bundle.mjs           生成并校验
 *   node scripts/build-bundle.mjs --check   只校验不写
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(dirname(fileURLToPath(import.meta.url)));
const BASE = process.env.DS_STACK_BASE || "ptc";
const PRESET_REL = join("node_modules/@deepseek-ai/dsh-web-app/presets", BASE + ".patch.yml");

/** 找到本机 DSH 安装根：先看 DSH_APP_ROOT，再试常见位置，最后从当前目录往上找。 */
function findAppRoot() {
  const tried = [];
  const candidates = [
    process.env.DSH_APP_ROOT,
    "C:/Users/admin/AppData/Roaming/dsh-tauri/dependencies/dsh",
    join(homedir(), "AppData/Roaming/dsh-tauri/dependencies/dsh"),
    join(homedir(), ".dsh/dependencies/dsh"),
    join(homedir(), ".local/share/dsh"),
    "/usr/local/lib/dsh",
    "/opt/dsh",
    "/usr/lib/dsh",
  ].filter(Boolean);
  for (const root of candidates) {
    tried.push(root);
    if (existsSync(join(root, PRESET_REL))) return { root, tried };
  }
  let dir = process.cwd();
  for (let i = 0; i < 8; i++) {
    tried.push(dir);
    if (existsSync(join(dir, PRESET_REL))) return { root: dir, tried };
    const up = dirname(dir);
    if (up === dir) break;
    dir = up;
  }
  return { root: null, tried };
}

const found = findAppRoot();
if (!found.root) {
  console.error("找不到本机 DSH 安装根（缺 " + PRESET_REL + "）。");
  console.error("试过这些位置：");
  for (const t of found.tried) console.error("  " + t);
  console.error("");
  console.error("解决办法：把 DSH 的安装根目录传给脚本，例如");
  console.error("  DSH_APP_ROOT=/path/to/dsh node scripts/build-bundle.mjs");
  console.error("（安装根 = 含有 node_modules/@deepseek-ai/dsh-web-app 的那一层）");
  process.exit(2);
}
const APP = found.root;
const STANDARD = join(APP, PRESET_REL);
const PERSONA = join(HERE, "presets", "persona.txt");
const OUT = join(HERE, "cordis.patch.yml");
const ORDER = Number(process.env.DS_STACK_ORDER || 20);
const GENERATED = "# Generated by scripts/build-bundle.mjs (base: " + BASE + ") — do not edit by hand.\n";
const INDENT = " ".repeat(16);

const base = readFileSync(STANDARD, "utf8");
const persona = readFileSync(PERSONA, "utf8").replace(/\r\n/g, "\n").trimEnd();

const sub = (text, from, to, label) => {
  if (!text.includes(from)) throw new Error(label + ": anchor not found in " + BASE + ".patch.yml");
  return text.replace(from, to);
};

// 1) 行 id
const rowFrom = "    - id: preset-" + BASE + "\n";
const rowTo = "    - id: preset-engineer\n";
// 2) config.id -> id + name + description
const idFrom = "        id: " + BASE + "\n";
const idTo = [
  "        id: engineer",
  "        name: Engineer mode",
  "        description: 8 个常驻 ds-* 技能 + 自动触发规则（修 bug→tdd/verify-loop，结构改动→grill/blueprint，审视→jury）+ 复述/先读后改/证据优先的工作纪律 + PROGRESS.md 换上下文（基底 " + BASE + "）。",
  "",
].join("\n");
// 3) order
const orderMatch = /^ {8}order: (\d+)$/m.exec(base);
if (!orderMatch) throw new Error("order: not found");
const orderFrom = "        order: " + orderMatch[1] + "\n";
const orderTo = "        order: " + ORDER + "\n";
// 4) persona prefix
const personaMatch = /^ {14}prefix: .*$/m.exec(base);
if (!personaMatch) throw new Error("persona prefix: not found");
const personaFrom = personaMatch[0] + "\n";
const personaTo = "              prefix: |-\n" + persona.split("\n").map((l) => (l ? INDENT + l : "")).join("\n") + "\n";
// 5) provider row after skill-filesystem
const skillFrom = "          - id: skill-filesystem\n            name: '@deepseek-ai/dsh-skill-filesystem'\n";
// 行里写的模块名必须等于包名，否则加载器解析不到（改名时最容易漏的一处）。
const PKG_NAME = JSON.parse(readFileSync(join(HERE, "package.json"), "utf8")).name;
const skillTo = skillFrom + "          - id: skill-engineer\n            name: " + PKG_NAME + "\n";

let body = sub(base, rowFrom, rowTo, "row id");
body = sub(body, idFrom, idTo, "config id");
body = sub(body, orderFrom, orderTo, "order");
body = sub(body, personaFrom, personaTo, "persona");
body = sub(body, skillFrom, skillTo, "skill row");
const output = GENERATED + body;

const reversed = output
  .replace(GENERATED, "")
  .replace(rowTo, rowFrom)
  .replace(idTo, idFrom)
  .replace(orderTo, orderFrom)
  .replace(personaTo, personaFrom)
  .replace(skillTo, skillFrom);
if (reversed !== base) throw new Error("round-trip check failed: output does not reverse to " + BASE);

console.log("app root: " + APP);
console.log("base: " + BASE + " | rows: preset-engineer(+skill-engineer) | order: " + ORDER + " | persona lines: " + persona.split("\n").length);
console.log("round-trip: ok");
if (process.argv.includes("--check")) { console.log("check: nothing written"); process.exit(0); }
writeFileSync(OUT, output);
console.log("wrote", OUT);
